//! Actions-only actual original SDK/consumer Group/P2P read-position status,
//! explicit manual intent, independent policies, SQL journal and original Join.
use super::*;
use n::im_read_status_policy::NativeReadStatusConfig;
fn configuration(root:&str,port:u16,enabled:bool)->AccountConfig{let mut c=config(root,port,false);c.profile.im_read_status=enabled.then_some(NativeReadStatusConfig{set_read_status:true});assert!(c.profile.im_receipts.is_none()&&c.profile.im_user_read.is_none());c}
fn group_status()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1-2").unwrap();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:b"0"},RpcProperty{key:n::im_status::LATEST,value:b"3"}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn initial(peer:&mut CommonPeer,group:bool){login_host(peer).await;let p=query(peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();peer.send(&[reply(r.call_id,&if group{group_status()}else{status(3,1)})]).await;let p=query(peer,n::im_data::RECV_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),if group{b"Org/1-2"}else{b"P2P/1_2"});assert_eq!(a.i64().unwrap(),1);assert_eq!(a.u32().unwrap(),3);a.finish().unwrap();peer.send(&[reply(r.call_id,&records(1,3))]).await;}
async fn scenario(group:bool,code:u32,yes:bool,cancel:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(configuration(&cert.root,port,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(sent,submitted)=tokio::sync::oneshot::channel();let(done,wait)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;initial(&mut peer,group).await;let p=query(&mut peer,n::im_data::SET_READ_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),if group{b"Org/1-2"}else{b"P2P/1_2"});assert_eq!(a.i64().unwrap(),3);a.finish().unwrap();let state:(i64,Option<i32>)=db.with_conn(|c|c.query_row("SELECT state,request_id FROM app_voice_im_read_status_actions",[],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|"fixture")).unwrap();assert_eq!(state,(0,Some(r.call_id)));sent.send(()).unwrap();if cancel{wait.await.unwrap();assert!(peer.next().await.is_none(),"unknown manual WRITE cannot send another setRead/unhosting/logout on retired IO");}else{peer.send(&[response(r.call_id,yes,code)]).await;wait.await.unwrap();finish_account(&mut peer).await;}}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(async{while manager.get(&line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await;let targets=bounded(async{loop{let v=manager.im_read_status_targets(&line,1).await.unwrap();if !v.is_empty(){break v;}tokio::task::yield_now().await;}}).await;let target=&targets[0];assert_eq!(target.box_kind,if group{"org"}else{"p2p"});assert_eq!(target.target_index,"3");assert!(manager.im_read_status_history(&line,16).unwrap().is_empty(),"span/read/installation is not explicit manual WRITE consent");assert_eq!(manager.set_im_read_status(&line,1,target.id,"3",&"a".repeat(32),false).await.err(),Some("app_account_im_read_status_consent_required"));assert_eq!(manager.set_im_read_status(&line,2,target.id,"3",&"a".repeat(32),true).await.err(),Some("app_account_revision_conflict"));assert_eq!(manager.set_im_read_status(&line,1,target.id,"4",&"a".repeat(32),true).await.err(),Some("app_account_im_read_status_target_conflict"));let nonce="a".repeat(32);let mut writing=Box::pin(manager.set_im_read_status(&line,1,target.id,"3",&nonce,true));
    if cancel{tokio::select!{result=&mut writing=>panic!("original manual WRITE has no reply: {result:?}"),_=bounded(submitted)=>{}}drop(writing);done.send(()).unwrap();bounded(async{while manager.get(&line,100).await.unwrap().phase!="disconnected"{tokio::task::yield_now().await;}}).await;assert_eq!(manager.im_read_status_history(&line,16).unwrap()[0].state,"uncertain");}else{let result=bounded(writing).await.unwrap();assert_eq!(result.state,if yes&&code==0{"confirmed"}else{"rejected"});let replay=manager.set_im_read_status(&line,1,target.id,"3",&nonce,true).await.unwrap();assert_eq!(replay.id,result.id);assert_eq!(replay.state,result.state);let public=serde_json::to_string(&result).unwrap();for private in ["Org/1-2","P2P/1_2","scope_epoch","user_nonce","box_id","span_hash","fixture"]{assert!(!public.contains(private));}done.send(()).unwrap();}
    let user_rows:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_user_reads",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(user_rows,0,"read-position is not P:P_UDMR-N user marking");assert_eq!(manager.im_messages(&line,16).unwrap().len(),3);assert!(manager.messages(&line,16).unwrap().is_empty());assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());let count:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_read_status_targets",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,0,"ephemeral target DATA retires only after original quiescence");
}
#[tokio::test]async fn read_status_account_original_group_manual_consent_uses_setRead_and_true_joins_without_user_grant(){Box::pin(scenario(true,0,true,false)).await;}
#[tokio::test]async fn read_status_account_original_uid_manual_position_has_separate_history_and_same_nonce_no_replay(){Box::pin(scenario(false,0,true,false)).await;}
#[tokio::test]async fn read_status_account_group_false_reply_is_known_rejected_not_automatic_received_retry(){Box::pin(scenario(true,0,false,false)).await;}
#[tokio::test]async fn read_status_account_original_version_error_is_negative_and_does_not_resend(){Box::pin(scenario(true,65537,false,false)).await;}
#[tokio::test]async fn read_status_account_full_manual_write_cancel_keeps_unknown_and_all_original_io_joins(){Box::pin(scenario(true,0,true,true)).await;}
async fn fresh_unknown(change_revision:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(configuration(&cert.root,port,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(observed,seen)=tokio::sync::oneshot::channel();let(first_cancel,cancel_ready)=tokio::sync::oneshot::channel();let(second_ready,second_seen)=tokio::sync::oneshot::channel();let(done,finish)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{
        let original_listener=listener.into_std().unwrap();let second=TcpListener::from_std(original_listener.try_clone().unwrap()).unwrap();let first=TcpListener::from_std(original_listener).unwrap();
        let mut peer=CommonPeer::open(first,server.clone()).await;initial(&mut peer,true).await;let p=query(&mut peer,n::im_data::SET_READ_METHOD).await;let id=decode_request(&p[1..]).unwrap().call_id;observed.send(id).unwrap();cancel_ready.await.unwrap();while let Some(p)=peer.next().await{poll(&mut peer,&p).await;}drop(peer);let state:(i64,Option<i32>)=db.with_conn(|c|c.query_row("SELECT state,request_id FROM app_voice_im_read_status_actions",[],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|"fixture")).unwrap();assert_eq!(state,(0,Some(id)));
        let mut peer=CommonPeer::open(second,server).await;login_host(&mut peer).await;let p=query(&mut peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1-2").unwrap();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:if change_revision{b"0"}else{b"4"}},RpcProperty{key:n::im_status::LATEST,value:b"4"}]).unwrap();w.i64(2).unwrap();w.bytes(b"").unwrap();peer.send(&[reply(r.call_id,w.finish().expose_to_transport())]).await;let p=query(&mut peer,n::im_data::RECV_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"Org/1-2");assert_eq!(a.i64().unwrap(),if change_revision{1}else{4},"higher remote report is not local consumed position");assert_eq!(a.u32().unwrap(),if change_revision{4}else{1});a.finish().unwrap();peer.send(&[reply(r.call_id,&records(if change_revision{1}else{4},if change_revision{4}else{1}))]).await;second_ready.send(()).unwrap();finish.await.unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,1,100)).await.unwrap();let target=bounded(async{loop{if let Some(v)=manager.im_read_status_targets(&line,1).await.ok().and_then(|mut v|v.pop()){break v;}tokio::task::yield_now().await;}}).await;let nonce="a".repeat(32);let mut writing=Box::pin(manager.set_im_read_status(&line,1,target.id,"3",&nonce,true));let id=tokio::select!{result=writing.as_mut()=>panic!("original manual reply absent: {result:?}"),value=bounded(seen)=>value.unwrap()};drop(writing);first_cancel.send(()).unwrap();bounded(async{while manager.get(&line,100).await.unwrap().phase!="disconnected"{tokio::task::yield_now().await;}}).await;assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(manager.im_read_status_history(&line,128).unwrap()[0].state,"uncertain");
    let revision=if change_revision{let updated=manager.replace(&line,1,configuration(&cert.root,port,true),100).await.unwrap();assert_eq!(updated.account.revision,2);2}else{1};
    let fresh=AccountManager::new(temp.database.clone());bounded(fresh.start(&line,revision,100)).await.unwrap();bounded(second_seen).await.unwrap();let current=bounded(async{loop{if let Some(v)=fresh.im_read_status_targets(&line,revision).await.ok().and_then(|mut v|v.pop()){if v.target_index=="4"{break v;}}tokio::task::yield_now().await;}}).await;assert_ne!(current.id,target.id);assert_eq!(fresh.set_im_read_status(&line,revision,current.id,"4",&nonce,true).await.err(),Some("app_account_im_read_status_nonce_conflict"));assert_eq!(fresh.set_im_read_status(&line,revision,current.id,"4",&"b".repeat(32),true).await.err(),Some("app_account_im_receipt_uncertain"));assert_eq!(fresh.im_read_status_history(&line,128).unwrap().len(),1);assert_eq!(fresh.im_read_status_history(&line,128).unwrap()[0].state,"uncertain");let receipt=receipt(&temp.database);assert_eq!(receipt,(0,Some(id),3));assert_eq!(fresh.im_messages(&line,16).unwrap().len(),if change_revision{7}else{4});assert_eq!(fresh.get(&line,100).await.unwrap().phase,"hosted");assert!(fresh.im_user_read_history(&line,16).unwrap().is_empty());done.send(()).unwrap();assert!(!bounded(fresh.stop(&line,revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(fresh.im_read_status_history(&line,128).unwrap()[0].state,"uncertain");assert_eq!(fresh.delete(&line,revision+1).await.err(),Some("app_account_revision_conflict"));bounded(fresh.delete(&line,revision)).await.unwrap();for table in ["app_voice_im_read_status_targets","app_voice_im_read_status_actions","app_voice_im_read_receipts"]{let count:i64=temp.database.with_conn(|c|c.query_row(&format!("SELECT COUNT(*) FROM {table}"),[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,0,"only explicit authorized account deletion removes private history");}
}
#[tokio::test]async fn read_status_account_unknown_survives_true_stop_and_fresh_manager_group_report_without_cross_nonce_or_user_ack(){Box::pin(fresh_unknown(false)).await;}
#[tokio::test]async fn read_status_account_configuration_revision_and_fresh_scope_never_clear_old_original_unknown(){Box::pin(fresh_unknown(true)).await;}
#[tokio::test]async fn read_status_account_default_absence_never_creates_manual_targets_or_write_intents(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(configuration(&cert.root,port,false),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(go,wait)=tokio::sync::oneshot::channel();let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;initial(&mut peer,true).await;ready.send(()).unwrap();wait.await.unwrap();finish_account(&mut peer).await;}).await});bounded(manager.start(&line,1,100)).await.unwrap();bounded(seen).await.unwrap();assert_eq!(manager.im_read_status_targets(&line,1).await.err(),Some("app_account_im_read_status_not_installed"));assert!(manager.im_read_status_history(&line,16).unwrap().is_empty());go.send(()).unwrap();assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
